  @Test
  fun contractCostParamEntryXdrRoundTripsThroughItsJsonTree() {
    assertRoundTripContractCostParamEntryXdr(sampleContractCostParamEntryXdr(1017, 0))
    assertRoundTripContractCostParamEntryXdr(sampleContractCostParamEntryXdr(1017, SAMPLE_DEPTH))
  }

  private fun assertRoundTripContractCostParamEntryXdr(value: ContractCostParamEntryXdr) {
    val tree = value.toXdrJsonElement()
    val text = ContractCostParamEntryXdr.fromXdrJsonElement(tree).toXdrJson()
    assertEquals(tree, ContractCostParamEntryXdr.fromXdrJson(text).toXdrJsonElement())
    assertEquals(text, ContractCostParamEntryXdr.fromXdrJson(text).toXdrJson())

    val writer = XdrWriter()
    ContractCostParamEntryXdr.fromXdrJsonElement(tree).encode(writer)
    assertEquals(tree, ContractCostParamEntryXdr.decode(XdrReader(writer.toByteArray())).toXdrJsonElement())
  }

  @Test
  fun contractCostParamEntryXdrRejectsInputThatIsNotItsObject() {
    assertFailsWith<IllegalArgumentException> { ContractCostParamEntryXdr.fromXdrJsonElement(JsonNull) }
    assertFailsWith<IllegalArgumentException> { ContractCostParamEntryXdr.fromXdrJsonElement(buildJsonObject { }) }
  }


