  @Test
  fun configSettingEntryXdrRejectsAnArmItDoesNotDeclare() {
    assertFailsWith<IllegalArgumentException> {
      ConfigSettingEntryXdr.fromXdrJsonElement(buildJsonObject { put("not_a_name_this_type_declares", JsonNull) })
    }
    assertFailsWith<IllegalArgumentException> {
      ConfigSettingEntryXdr.fromXdrJsonElement(
        buildJsonObject {
          put("not_a_name_this_type_declares", JsonNull)
          put("not_a_name_this_type_declares_too", JsonNull)
        }
      )
    }
    assertFailsWith<IllegalArgumentException> { ConfigSettingEntryXdr.fromXdrJsonElement(JsonNull) }
  }

